function validate([tomatoSlices, cheeseSlices]) {
  if (!Number.isInteger(tomatoSlices) || tomatoSlices < 0 || tomatoSlices > 1e7) return 'tomatoSlices is a whole number from 0 to 10^7.';
  if (!Number.isInteger(cheeseSlices) || cheeseSlices < 0 || cheeseSlices > 1e7) return 'cheeseSlices is a whole number from 0 to 10^7.';
  return null;
}

