function numOfBurgers(tomatoSlices, cheeseSlices) {
  for (let jumbo = 0; jumbo <= cheeseSlices; jumbo++) {
    const small = cheeseSlices - jumbo;
    if (4 * jumbo + 2 * small === tomatoSlices) return [jumbo, small];
  }
