function generate(rand, size) {
  const pick = (limit) => Math.floor(rand() * (limit + 1));
  if (size === 'small') {
    if (rand() < 0.5) {
      const jumbo = pick(6), small = pick(6);
      return [4 * jumbo + 2 * small, jumbo + small];
    }
    return [pick(30), pick(12)];
  }
  if (rand() < 0.6) {
    // Build a solvable input: 4 * 1,000,000 + 2 * 3,000,000 stays within 10^7.
    const jumbo = pick(1000000), small = pick(3000000);
    return [4 * jumbo + 2 * small, jumbo + small];
  }
  return [pick(10000000), pick(10000000)];
}
